        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val pointer: Pointer?) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_dspi_core_fn_free_deviceevents(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_dspi_core_fn_clone_deviceevents(pointer!!, status)
        }
    }

    
    /**
     * A DSPi with this serial appeared on the bus.
     */override fun `onArrived`(`serial`: kotlin.String)
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_dspi_core_fn_method_deviceevents_on_arrived(
        it, FfiConverterString.lower(`serial`),_status)
}
    }
    
    

    
    /**
     * The DSPi with this serial left the bus, or the open device was lost.
     */override fun `onDeparted`(`serial`: kotlin.String)
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_dspi_core_fn_method_deviceevents_on_departed(
        it, FfiConverterString.lower(`serial`),_status)
}
    }
    
    

    

    
    
    companion object
    
}


