     * transfer errors of every setter.
     */
    fun `setLevellerMaxGain`(`db`: kotlin.Float)
    
    /**
     * 0 slow, 1 medium, 2 fast.
     *
     * Errors: [`DspiError::InvalidArgument`] for another speed; the
     * connection and transfer errors of every setter.
     */
    fun `setLevellerSpeed`(`speed`: kotlin.UByte)
    
    /**
     * LG Sound Sync on or off: live, saved with the preset. Sets
     * `DspState.lg_sound_sync_enabled`.
     *
     * Errors: [`DspiError::ReadOnly`], [`DspiError::Disconnected`] or a
     * transfer error.
     */
    fun `setLgSoundSync`(`enabled`: kotlin.Boolean)
    
    /**
     * Set one output-limiter parameter of `output` (0-based), or of every
     * output when `output` is `LIMITER_ALL_OUTPUTS` (0xFF). `param`:
     * `LIMITER_PARAM_*` (enabled: non-zero is on; threshold dB -30..0;
     * release ms 10..1000; link group 0..4, 0 = unlinked), clamped as the
     * firmware does. The mirror follows the firmware's link groups: a write
     * to one member moves the whole group, joining a group adopts its
     * settings, and a group set on every output gangs each group to its
     * lowest member.
     *
     * Errors: `InvalidArgument` (unknown `param`, NaN, an output past the
     * device's), `Disconnected`, `ReadOnly`, `Unsupported` (no limiter),
     * `Transfer`.
     */
    fun `setLimiterParam`(`output`: kotlin.UByte, `param`: kotlin.UByte, `value`: kotlin.Float)
    
    /**
     * Register (`Some`) or clear (`None`) the session events listener. Same
     * rules as the other listeners: called with the core lock released, and
     * clearing waits for a call in progress.
     */
    fun `setLinkListener`(`listener`: LinkListener?)
    
    /**
     * Loudness compensation on (`true`) or off.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    fun `setLoudness`(`enabled`: kotlin.Boolean)
    
    /**
     * Loudness intensity in percent, clamped to 0..200 as the firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    fun `setLoudnessIntensity`(`pct`: kotlin.Float)
    
    /**
     * Bit k: loudness compensates output k.
     *
     * Errors: [`DspiError::Unsupported`] on firmware without the per-output
     * mask; the connection and transfer errors of every setter.
     */
    fun `setLoudnessMask`(`mask`: kotlin.UShort)
    
    /**
     * Loudness reference level in dB SPL, clamped to 40..100 as the
     * firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    fun `setLoudnessRef`(`spl`: kotlin.Float)
    
    /**
     * Device master volume in dB: −128 (or anything below) mutes, otherwise
     * −127..0 in 0.5 dB steps (rounded, then clamped).
     *
     * The firmware answers with the legacy v1 volume notification and then
     * a `PARAM_CHANGED`; both are the echo of this write.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    fun `setMasterVolume`(`db`: kotlin.Float)
    
    /**
     * 0 = master volume independent of presets, 1 = saved with presets.
     *
     * Errors: [`DspiError::InvalidArgument`] for another mode; the
     * connection and transfer errors of every setter.
     */
    fun `setMasterVolumeMode`(`mode`: kotlin.UByte)
    
    /**
