/**
 * Why a [`crate::DspiCore`] call failed.
 */
sealed class DspiException: kotlin.Exception() {
    
    /**
     * No device is open, or it went away.
     */
    class Disconnected(
        ) : DspiException() {
        override val message
            get() = ""
    }
    
    /**
     * A transfer failed (timeout, stall, short read, flash blackout).
     */
    class Transfer(
        
        /**
         * What failed, for a log or an error line.
         */
        val `msg`: kotlin.String
        ) : DspiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * The device answered but refused: the raw status byte (`PRESET_*`,
     * `PIN_CONFIG_*`, `FLASH_*`, or a command-specific code).
     */
    class Refused(
        
        /**
         * The status byte, never 0.
         */
        val `status`: kotlin.UByte
        ) : DspiException() {
        override val message
            get() = "status=${ `status` }"
    }
    
    /**
     * Bad argument (index out of range, malformed JSON op, ...).
     */
    class InvalidArgument(
        
        /**
         * Which argument, and why.
         */
        val `msg`: kotlin.String
        ) : DspiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * The firmware or transport does not have this feature.
     */
    class Unsupported(
        ) : DspiException() {
        override val message
            get() = ""
    }
    
    /**
     * The device's wire format is not this build's: its state is shown
     * read-only and nothing may be written.
     */
    class ReadOnly(
        ) : DspiException() {
        override val message
            get() = ""
    }
    
    /**
     * DSPi Link: another console holds the device lock.
     */
    class Locked(
        ) : DspiException() {
        override val message
            get() = ""
    }
    
    /**
     * DSPi Link: this session's role may not send that command.
     */
    class Denied(
        ) : DspiException() {
        override val message
            get() = ""
    }
    
    /**
     * DSPi Link session failure. `code`: `wrong_pin`, `rate_limited`,
     * `hub_busy`, `handshake_refused`, `io`, `handshake`, `protocol`,
     * `timeout`, `closed`, or another spec 7.1 error code. `msg` can be shown.
     */
    class Link(
        
        /**
         * The error code, as above.
         */
        val `code`: kotlin.String, 
        
        /**
         * The hub's or the client's words, for the user.
         */
        val `msg`: kotlin.String
        ) : DspiException() {
        override val message
            get() = "code=${ `code` }, msg=${ `msg` }"
    }
    
    /**
     * A file could not be read or written (presets, firmware images).
     */
    class Io(
        
        /**
         * What failed, with the operating system's reason.
         */
        val `msg`: kotlin.String
        ) : DspiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * An AutoEQ database update failed (`crate::autoeq`). `code`:
     * `rate_limited`, `http_status`, `network`, `bad_content`, `no_profiles`,
     * `too_many_failures`, `cancelled`, `stopped` or `missing`. `msg` can be
     * shown.
     */
    class AutoEq(
        
        /**
         * The failure, as above.
         */
        val `code`: kotlin.String, 
        
        /**
         * The words for the user.
         */
        val `msg`: kotlin.String, 
        
        /**
         * With `rate_limited`: seconds until it is worth trying again, when
         * the server said.
         */
        val `retryAfterS`: kotlin.UInt?
        ) : DspiException() {
        override val message
            get() = "code=${ `code` }, msg=${ `msg` }, retryAfterS=${ `retryAfterS` }"
    }
    
    /**
     * The firmware guard stopped an image that can leave the board at too low
     * a core voltage (`firmware_guard_check`); nothing was written.
     */
    class FirmwareGuardBlocked(
        
        /**
         * The guard's words, for the user.
         */
        val `msg`: kotlin.String
        ) : DspiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * This raises the core voltage above 1.20 V from what the unit reports
     * now, and the word `OVERVOLT` was not given. Nothing was written.
     */
    class OvervoltWordRequired(
        
        /**
         * Which voltage, and what to type.
         */
        val `msg`: kotlin.String
        ) : DspiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DspiException> {
        override fun lift(error_buf: RustBuffer.ByValue): DspiException = FfiConverterTypeDspiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeDspiError : FfiConverterRustBuffer<DspiException> {
    override fun read(buf: ByteBuffer): DspiException {
        

        return when(buf.getInt()) {
            1 -> DspiException.Disconnected()
            2 -> DspiException.Transfer(
                FfiConverterString.read(buf),
                )
            3 -> DspiException.Refused(
                FfiConverterUByte.read(buf),
                )
            4 -> DspiException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            5 -> DspiException.Unsupported()
            6 -> DspiException.ReadOnly()
            7 -> DspiException.Locked()
            8 -> DspiException.Denied()
            9 -> DspiException.Link(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            10 -> DspiException.Io(
                FfiConverterString.read(buf),
                )
            11 -> DspiException.AutoEq(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalUInt.read(buf),
                )
            12 -> DspiException.FirmwareGuardBlocked(
                FfiConverterString.read(buf),
                )
            13 -> DspiException.OvervoltWordRequired(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DspiException): ULong {
        return when(value) {
            is DspiException.Disconnected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DspiException.Transfer -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is DspiException.Refused -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUByte.allocationSize(value.`status`)
            )
            is DspiException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is DspiException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DspiException.ReadOnly -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DspiException.Locked -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DspiException.Denied -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DspiException.Link -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is DspiException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is DspiException.AutoEq -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`msg`)
                + FfiConverterOptionalUInt.allocationSize(value.`retryAfterS`)
            )
            is DspiException.FirmwareGuardBlocked -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is DspiException.OvervoltWordRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: DspiException, buf: ByteBuffer) {
        when(value) {
            is DspiException.Disconnected -> {
                buf.putInt(1)
                Unit
            }
            is DspiException.Transfer -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is DspiException.Refused -> {
                buf.putInt(3)
                FfiConverterUByte.write(value.`status`, buf)
                Unit
            }
            is DspiException.InvalidArgument -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is DspiException.Unsupported -> {
                buf.putInt(5)
                Unit
            }
            is DspiException.ReadOnly -> {
                buf.putInt(6)
                Unit
            }
            is DspiException.Locked -> {
                buf.putInt(7)
                Unit
            }
            is DspiException.Denied -> {
                buf.putInt(8)
                Unit
            }
            is DspiException.Link -> {
                buf.putInt(9)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is DspiException.Io -> {
                buf.putInt(10)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is DspiException.AutoEq -> {
                buf.putInt(11)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`msg`, buf)
                FfiConverterOptionalUInt.write(value.`retryAfterS`, buf)
                Unit
            }
            is DspiException.FirmwareGuardBlocked -> {
                buf.putInt(12)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is DspiException.OvervoltWordRequired -> {
                buf.putInt(13)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * How an output's fill reads ([`OutputFill::band`]). The Console shows these
 * green, yellow and red.
 */

enum class FillBand {
    
    /**
     * Within the expected swing.
     */
    GOOD,
    /**
     * Outside the expected swing.
     */
    WARN,
    /**
     * Empty, or too full to take a write.
     */
    BAD;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFillBand: FfiConverterRustBuffer<FillBand> {
    override fun read(buf: ByteBuffer) = try {
        FillBand.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
